using System;
using System.Reflection;
namespace Downfield {
public static class LinePlayTests {
 static int checks,failures;static void Check(bool ok,string name){checks++;if(!ok){failures++;Console.WriteLine("FAIL Line play: "+name);}}
 public static Simulation TruckScene(int seed){Simulation s=new Simulation(seed);s.Players.Clear();Player runner=new Player(0,24,0,"RB",22,8);runner.Power=99;runner.HasBall=true;Player defender=new Player(0,24.6f,1,"LB",54,7);defender.Power=70;s.Players.Add(runner);s.Players.Add(defender);s.Controlled=runner;s.State=Phase.Live;s.SkillMove(0,1);return s;}
 public static int Run(){Simulation s=new Simulation(713);int straight=0,stunts=0;bool adjacent=false,last=false,pairs=true;bool left=false,right=false;for(int play=0;play<800;play++){s.NewGame();bool active=s.RushPlan!="STRAIGHT";if(active){stunts++;if(last)adjacent=true;int assigned=0,loopers=0;foreach(Player p in s.Players)if(p.Role=="DL"&&p.RushAssignment!=0){assigned++;if(p.RushAssignment==2){loopers++;if(p.StartX<0)left=true;else right=true;}}if(assigned!=2||loopers!=1)pairs=false;}else straight++;last=active;}Console.WriteLine("Rush mix: "+straight+" straight / "+stunts+" stunts across 800 calls");Check(straight>550&&stunts>80,"straight rush is default with occasional stunts");Check(!adjacent,"no consecutive stunt calls");Check(pairs&&left&&right,"only one varied two-man stunt pair per call");
  bool bounded=true,paired=true,contact=false;int engaged=0;for(int seed=0;seed<45;seed++){s=new Simulation(30000+seed);s.Snap();for(int frame=0;frame<360&&s.State==Phase.Live;frame++){float[] x=new float[s.Players.Count],z=new float[s.Players.Count];for(int i=0;i<s.Players.Count;i++){x[i]=s.Players[i].X;z[i]=s.Players[i].Z;}s.Update(1f/60,0,0);for(int i=11;i<s.Players.Count;i++){Player p=s.Players[i];if(p.Role!="DL")continue;if(p.KnockTime<=0&&Simulation.Distance(p.X,p.Z,x[i],z[i])>.4f)bounded=false;if(p.BlockPartner>=0){engaged++;Player blocker=s.Players[p.BlockPartner];if(blocker.BlockPartner!=i)paired=false;if(p.Z<blocker.Z-.4f)contact=true;}}}}Check(bounded,"rushers have bounded grounded movement through full live plays");Check(paired&&engaged>100,"blocking partnerships stay one-to-one");Check(!contact,"engaged rushers cannot phase through blockers");
  Simulation won=null,lost=null;for(int seed=1;seed<120&&(won==null||lost==null);seed++){s=TruckScene(seed);s.Update(1f/60,0,1);if(s.Players[1].KnockTime>0)won=s;else if(s.Controlled.KnockTime>0&&s.State==Phase.Dead)lost=s;}Check(won!=null&&lost!=null,"real truck contacts produce success and failure outcomes");if(won!=null){Player d=won.Players[1];float initial=d.Z;for(int i=0;i<24;i++)won.Update(1f/60,0,1);Check(d.Z-initial>1.5f&&d.Pose=="knockdown"&&d.KnockTime>0,"successful truck launches defender backward and keeps him down");Check(won.State==Phase.Live&&won.Controlled.KnockTime==0,"successful runner keeps control during fall animation");}
  if(lost!=null){float initial=lost.Controlled.Z,spot=lost.Spot;for(int i=0;i<24;i++)lost.Update(1f/60,0,0);Check(initial-lost.Controlled.Z>1.5f&&lost.Controlled.Pose=="knockdown","failed truck throws runner backward after whistle");Check(lost.Spot==spot&&lost.HitFlash>0,"fall animation preserves dead-ball spot and remains visible");for(int i=0;i<60;i++)lost.Update(1f/60,0,0);Check(lost.Controlled.KnockTime==0,"knockdown finishes without getting stuck");}
  Console.WriteLine("Line play: "+checks+" checks, "+failures+" failures");return failures;}
}
}
